@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_containerRef">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _containerRef;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _jsModule.InvokeVoidAsync("initialize", _containerRef, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        await OnIdle.InvokeAsync();
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        await OnActive.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("dispose");
            await _jsModule.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let state = null;

export function initialize(container, dotNetRef, timeoutMs) {
    const events = ["mousemove", "keydown", "click", "scroll"];
    let timerId = null;
    let isIdle = false;

    function resetTimer() {
        if (timerId !== null) {
            clearTimeout(timerId);
        }

        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnUserActive");
        }

        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnUserIdle");
        }, timeoutMs);
    }

    events.forEach(evt => container.addEventListener(evt, resetTimer, { passive: true }));

    // Also listen on document to capture activity outside the container but within the page
    events.forEach(evt => document.addEventListener(evt, resetTimer, { passive: true }));

    // Start the initial timer
    resetTimer();

    state = { container, events, timerId: () => timerId, resetTimer };
}

export function dispose() {
    if (state) {
        const { container, events, timerId, resetTimer } = state;
        clearTimeout(timerId());
        events.forEach(evt => container.removeEventListener(evt, resetTimer));
        events.forEach(evt => document.removeEventListener(evt, resetTimer));
        state = null;
    }
}

